const listAdminUsers = `-- name: ListAdminUsers :many
SELECT admin_id, login_name, display_name, auth_source, role, status, created_at, updated_at, activated_at, disabled_at, last_login_at FROM control_admin_users
ORDER BY login_name, admin_id
`

func (q *Queries) ListAdminUsers(ctx context.Context) ([]ControlAdminUser, error) {
	rows, err := q.db.Query(ctx, listAdminUsers)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ControlAdminUser{}
	for rows.Next() {
		var i ControlAdminUser
		if err := rows.Scan(
			&i.AdminID,
			&i.LoginName,
			&i.DisplayName,
			&i.AuthSource,
			&i.Role,
			&i.Status,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ActivatedAt,
			&i.DisabledAt,
			&i.LastLoginAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

