const upsertAdminPassword = `-- name: UpsertAdminPassword :one
INSERT INTO control_admin_passwords (admin_id, password_phc, parameter_version)
VALUES ($1, $2, $3)
ON CONFLICT (admin_id) DO UPDATE
SET password_phc = EXCLUDED.password_phc,
    parameter_version = EXCLUDED.parameter_version,
    changed_at = CURRENT_TIMESTAMP
RETURNING admin_id, password_phc, parameter_version, changed_at
`

type UpsertAdminPasswordParams struct {
	AdminID          pgtype.UUID `json:"admin_id"`
	PasswordPhc      string      `json:"password_phc"`
	ParameterVersion int32       `json:"parameter_version"`
}

func (q *Queries) UpsertAdminPassword(ctx context.Context, arg UpsertAdminPasswordParams) (ControlAdminPassword, error) {
	row := q.db.QueryRow(ctx, upsertAdminPassword, arg.AdminID, arg.PasswordPhc, arg.ParameterVersion)
	var i ControlAdminPassword
	err := row.Scan(
		&i.AdminID,
		&i.PasswordPhc,
		&i.ParameterVersion,
		&i.ChangedAt,
	)
	return i, err
}

const upsertAdminTOTP = `-- name: UpsertAdminTOTP :one
INSERT INTO control_admin_totp (admin_id, encrypted_secret, nonce, key_version)
VALUES ($1, $2, $3, $4)
ON CONFLICT (admin_id) DO UPDATE
SET encrypted_secret = EXCLUDED.encrypted_secret,
    nonce = EXCLUDED.nonce,
    key_version = EXCLUDED.key_version,
    created_at = CURRENT_TIMESTAMP,
    confirmed_at = NULL,
    last_used_step = NULL
RETURNING admin_id, encrypted_secret, nonce, key_version, created_at, confirmed_at, last_used_step
`

type UpsertAdminTOTPParams struct {
	AdminID         pgtype.UUID `json:"admin_id"`
	EncryptedSecret []byte      `json:"encrypted_secret"`
	Nonce           []byte      `json:"nonce"`
	KeyVersion      int32       `json:"key_version"`
}

func (q *Queries) UpsertAdminTOTP(ctx context.Context, arg UpsertAdminTOTPParams) (ControlAdminTotp, error) {
	row := q.db.QueryRow(ctx, upsertAdminTOTP,
		arg.AdminID,
		arg.EncryptedSecret,
		arg.Nonce,
		arg.KeyVersion,
	)
	var i ControlAdminTotp
	err := row.Scan(
		&i.AdminID,
		&i.EncryptedSecret,
		&i.Nonce,
		&i.KeyVersion,
		&i.CreatedAt,
		&i.ConfirmedAt,
		&i.LastUsedStep,
	)
	return i, err
}
